INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1092099', 'Battle of Skuodas', 'The Battle of Skuodas or Schoden was fought in ca. 1259 near Skuodas in present-day Lithuania during the Lithuanian Crusade.', 1258, NULL, NULL, NULL, NULL, NULL, 'year', '1258', 37, 'https://en.wikipedia.org/wiki/Battle_of_Skuodas_(1259)'),
  ('Q3920750', 'Battle of Medininkai', 'The Battle of Medininkai took place on 27 July 1320 between the Teutonic Order and the Samogitian army near Medininkai (now Varniai).', 1320, 7, 27, NULL, NULL, NULL, 'day', '27 July 1320', 43, 'https://en.wikipedia.org/wiki/Battle_of_Medininkai'),
  ('Q12660036', 'Siege of Kaunas', 'The siege of Kaunas was laid by the Teutonic Order on the newly built Kaunas Castle in spring 1362. It was the first brick castle built by the Grand Duchy of Lithuania.', 1362, 3, 13, 1362, 4, 17, 'day', '13 March 1362 – 17 April 1362', 37, 'https://en.wikipedia.org/wiki/Siege_of_Kaunas_(1362)'),
  ('Q1411508', 'Battle of Wilkomierz', 'The Battle of Wiłkomierz (see other names) took place on September 1, 1435, near Ukmergė in the Grand Duchy of Lithuania. With the help of military units from the Kingdom of Poland, the forces of Grand Duke Sigismund Kęstutaitis soundly defeated Švitrigaila and his Livonian allies.', 1435, 9, 1, NULL, NULL, NULL, 'day', '1 September 1435', 50, 'https://en.wikipedia.org/wiki/Battle_of_Wi%C5%82komierz'),
  ('Q653379', 'Union of Kraków and Vilna', 'The Union of Kraków and Vilna, also known as Union of Vilnius, was one of the agreements of the Polish–Lithuanian union. It was signed in Kraków by the Polish nobility on 6 May 1499, and in Vilnius by the Lithuanian nobility on 24 July 1499.', 1499, 5, 6, NULL, NULL, NULL, 'day', '6 May 1499', 50, 'https://en.wikipedia.org/wiki/Union_of_Krak%C3%B3w_and_Vilna'),
  ('Q1267481', 'Treaty of Vilnius', 'The Treaty of Vilnius was concluded on 28 November 1561, during the Livonian War, between the Livonian Confederation and the Grand Duchy of Lithuania in Vilnius. With the treaty, the non-Danish and non-Swedish part of Livonia, with the exception of the Free imperial city of Riga, subjected itself to the Grand Duke of Lithuania, Sigismund II Augustus with the Pacta subiectionis (Provisio ducalis).', 1561, 11, 28, NULL, NULL, NULL, 'day', '28 November 1561', 52, 'https://en.wikipedia.org/wiki/Treaty_of_Vilnius_(1561)'),
  ('Q4087367', 'Battle of Vilnius', 'The Battle of Vilnius was an attack by Russian and Cossack forces on Vilnius, the capital of the Grand Duchy of Lithuania within the Polish–Lithuanian Commonwealth, that occurred on 8 August 1655 during the Russo-Polish War (1654–67). The Polish–Lithuanian forces under the leadership of Grand Hetman of Lithuania Janusz Radziwiłł were defeated by the Russian army of Alexis of Russia.', 1655, 7, 29, 1655, 7, 31, 'day', '29 July 1655 – 31 July 1655', 47, 'https://en.wikipedia.org/wiki/Battle_of_Vilnius_(1655)'),
  ('Q1502680', 'Truce of Vilna', 'The Truce of Vilna, Treaty of Wilno or Truce or Treaty of Niemieża was a treaty signed at Niemieża (modern Nemėžis) near Vilnius (also known as Vilna or Wilno) on 3 November 1656 between the Tsardom of Russia and Polish–Lithuanian Commonwealth, introducing a truce during the Russo-Polish War (1654–67) and an anti-Swedish alliance in the contemporaneous Second Northern War. In return for ceasing hostilities and fighting Sweden alongside Poland–Lithuania, the treaty promised tsar Alexis of Russia to succeed the Polish–Lithuanian throne as soon as John II Casimir Vasa would die.', 1656, 10, 24, NULL, NULL, NULL, 'day', '24 October 1656', 47, 'https://en.wikipedia.org/wiki/Truce_of_Vilna'),
  ('Q4087366', 'Battle of Werki', 'Battle of Verkiai fought in autumn of 1658 between the Polish–Lithuanian Commonwealth and the Tsardom of Russia marked the resumption of hostilities in the Russo-Polish War (1654–67); it ended with Russian victory. Russians, close to signing a peace treaty with Sweden (truce of Valiersari ending the Russo–Swedish War (1656–58)) decided to resume the war with Poland in order to gain control over the disputed Ruthenian territories.', 1658, 9, 24, 1658, 10, 11, 'day', '24 September 1658 – 11 October 1658', 41, 'https://en.wikipedia.org/wiki/Battle_of_Verkiai'),
  ('Q4871943', 'Battle of Olkieniki', 'The Battle of Valkininkai (Lithuanian: Valkininkų mūšis, Polish: Bitwa pod Olkienikami) took place on November 18, 1700, during the Lithuanian Civil War, between forces of the Sapieha family, led by Michał Franciszek Sapieha, and an anti-Sapieha coalition of Wiśniowiecki, Ogiński, Radziwiłł and Pac families and their supporters (including a pospolite ruszenie of Lithuanian and Samogitian szlachta), led by Michał Serwacy Wiśniowiecki. The anti-Sapieha confederates were victorious.', 1700, 11, 18, NULL, NULL, NULL, 'day', '18 November 1700', 37, 'https://en.wikipedia.org/wiki/Battle_of_Valkininkai_(1700)'),
  ('Q9172660', 'Battle of Vilnius', 'The Battle of Vilnius took place on 16 April 1702 (N.S.) in Vilnius, the capital of the Grand Duchy of Lithuania, during the Great Northern War.', 1702, NULL, NULL, NULL, NULL, NULL, 'year', '1702', 39, 'https://en.wikipedia.org/wiki/Battle_of_Vilnius_(1702)'),
  ('Q9173542', 'Battle of Saločiai (1794)', 'Battle of Saločiai (Lithuanian: Saločių kautynės, Russian: Бой под Салатами, Polish: Bitwa pod Sałatami) was a battle fought during the Kościuszko Uprising on July 29, 1794, between the troops of Grand Duchy of Lithuania under the command of General Prince Romuald Giedroyć and the Russian troops of Prince Sergei Fedorovich Golitsyn.', 1794, 7, 29, NULL, NULL, NULL, 'day', '29 July 1794', 37, 'https://en.wikipedia.org/wiki/Battle_of_Salo%C4%8Diai_(1794)'),
  ('Q620222', 'Sventiany Offensive', 'The Battle of Vilnius (German: Schlacht bei Wilna) or the Vilnius operation (Russian: Виленская операция) took place in the autumn of 1915 between the cities of Vilnius and Daugavpils. It was strategic withdrawal by Russian forces on the Eastern Front of World War I, after a successful summer German offensive.', 1915, 8, 26, 1915, 10, 2, 'day', '26 August 1915 – 2 October 1915', 50, 'https://en.wikipedia.org/wiki/Battle_of_Vilnius_(1915)'),
  ('Q166981', 'Act of Independence of Lithuania', 'The Act of Independence of Lithuania (Lithuanian: Lietuvos Nepriklausomybės Aktas) or the Act of February 16th, also the Lithuanian Resolution on Independence (Lithuanian: Lietuvos Nepriklausomybės Nutarimas), was signed by the Council of Lithuania on February 16, 1918. It proclaimed independence from Russia and the restoration of an independent State of Lithuania, governed by democratic principles, with Vilnius as its capital.', 1918, 2, 16, NULL, NULL, NULL, 'day', '16 February 1918', 67, 'https://en.wikipedia.org/wiki/Act_of_Independence_of_Lithuania'),
  ('Q172240', 'Battles for Vilnius', 'The Battle of Vilnius in January 1919 (Polish: Walki o Wilno, Russian: Сражения за Вильно) were a series of battles fought in Vilnius between the pro-Polish Self-Defence of Lithuania and Belarus who were initially against the Imperial German Army retreating from the city and the Bolshevik paramilitaries (December 31, 1918 – January 3, 1919) and then against the attacking Red Army (January 4–5, 1919). The fighting resulted in the temporary capture of most of the city of Vilnius by the Poles, who eventually had to retreat before the Red Army came.', 1918, 12, 31, 1919, 1, 5, 'day', '31 December 1918 – 5 January 1919', 34, 'https://en.wikipedia.org/wiki/Battle_of_Vilnius_(January_1919)'),
  ('Q1604816', 'Lithuanian–Soviet War', 'The Lithuanian–Soviet War or Lithuanian–Bolshevik War (Lithuanian: karas su bolševikais) was fought between newly independent Lithuania and the Russian Socialist Federative Soviet Republic in the aftermath of World War I. It was part of the larger Soviet westward offensive of 1918–1919. The offensive followed the retreat of German troops and sought to establish Soviet republics in Ukraine, Belarus, Lithuania, Latvia, Estonia, and Poland, and to link up with the German Revolution.', 1918, 12, NULL, 1919, 8, NULL, 'month', 'December 1918 – August 1919', 57, 'https://en.wikipedia.org/wiki/Lithuanian%E2%80%93Soviet_War'),
  ('Q2742886', 'Lithuanian Wars of Independence', 'The Lithuanian Wars of Independence (Lithuanian: Lietuvos nepriklausomybės kovos), also known as the Freedom Struggles (Lithuanian: Laisvės kovos), refer to three wars Lithuania fought defending its independence at the end of World War I: with Bolshevik forces (December 1918 – August 1919), Bermontians (October 1919 – December 1919), and Poland (April 1919 – November 1920). The wars delayed international recognition of Lithuania''s restored independence and the establishment of its civil institutions.', 1918, 12, NULL, 1919, 8, NULL, 'month', 'December 1918 – August 1919', 60, 'https://en.wikipedia.org/wiki/Lithuanian_Wars_of_Independence'),
  ('Q3089540', 'Soviet westward offensive of 1918–1919', 'The Soviet westward offensive of 1918–1919 was part of the campaign by Soviet Russia into areas abandoned by the Ober Ost garrisons that were being withdrawn to Germany following that country''s defeat in World War I. The initially successful offensive against the Republic of Estonia ignited the Estonian War of Independence which ended with the Soviet recognition of Estonia. Similarly, the campaigns against the Republic of Latvia and Republic of Lithuania ultimately failed, resulting in the Latvian–Soviet Peace Treaty and Soviet–Lithuanian Peace Treaty respectively.', 1918, 11, 18, 1919, 3, NULL, 'day', '18 November 1918 – March 1919', 52, 'https://en.wikipedia.org/wiki/Soviet_westward_offensive_of_1918%E2%80%931919'),
  ('Q65216079', 'Battle of Radviliškis', 'The Battle of Radviliškis (Lithuanian: Radviliškio kautynės) was fought between the Lithuanian Armed Forces and the Western Russian Volunteer Army, also known as Bermontians, a pro-German military formation, commanded by Pavel Bermondt-Avalov near the city of Radviliškis as part of the Lithuanian Wars of Independence. Fought on 21–22 November 1919, it saw the decisive defeat of the Bermontians and their subsequent retreat from the Baltic States.', 1919, 11, NULL, 1919, 11, 22, 'month', 'November 1919 – 22 November 1919', 34, 'https://en.wikipedia.org/wiki/Battle_of_Radvili%C5%A1kis'),
  ('Q29321', 'Soviet–Lithuanian Peace Treaty', 'The Soviet–Lithuanian Peace Treaty, also known as the Moscow Peace Treaty, was signed between Lithuania and Soviet Russia on July 12, 1920. In exchange for Lithuania''s neutrality and permission to move its troops in the territory that was recognised during its war against Poland, Soviet Russia recognized the sovereignty of Lithuania.', 1920, 7, 12, NULL, NULL, NULL, 'day', '12 July 1920', 57, 'https://en.wikipedia.org/wiki/Soviet%E2%80%93Lithuanian_Peace_Treaty'),
  ('Q1495944', 'Polish–Lithuanian War', 'The Polish–Lithuanian War was an undeclared war fought in the aftermath of World War I between newly independent Lithuania and Poland, with fighting mainly in the Vilnius and Suwałki regions, which was part of the Lithuanian Wars of Independence and lasted from May 1919 to 29 November 1920. From the spring of 1920 onward, the conflict happened alongside the wider Polish–Soviet War and was affected by its progress.', 1920, 11, 29, 1920, NULL, NULL, 'day', '1920', 64, 'https://en.wikipedia.org/wiki/Polish%E2%80%93Lithuanian_War'),
  ('Q3358934', 'Klaipėda Revolt', 'The Klaipėda Revolt took place in January 1923 in the Klaipėda Region (also known as the Memel Territory or Memelland). The region, located north of the Neman River, was detached from East Prussia, German Empire by the Treaty of Versailles and became a mandate of the League of Nations.', 1923, NULL, NULL, 1923, 1, 15, 'year', '1923', 55, 'https://en.wikipedia.org/wiki/Klaip%C4%97da_Revolt'),
  ('Q167759', 'Baltic Entente', 'The Baltic Entente was based on Treaty of Good-Understanding and Co-operation signed between Lithuania, Latvia, and Estonia on 12 September 1934 in Geneva. The main objective of the agreement was joint action in foreign policy.', 1934, 9, 12, NULL, NULL, NULL, 'day', '12 September 1934', 65, 'https://en.wikipedia.org/wiki/Baltic_Entente'),
  ('Q4090297', 'Battle of Wilno', 'The Battle of Wilno (modern Vilnius, Lithuania) was fought by the Polish Army against the Soviet invasion of Poland in 1939, which accompanied the German Invasion of Poland in accordance with Molotov–Ribbentrop Pact. On 18–19 September, Soviet forces took over the city of Wilno.', 1939, 9, 18, 1939, 9, 19, 'day', '18 September 1939 – 19 September 1939', 43, 'https://en.wikipedia.org/wiki/Battle_of_Wilno_(1939)'),
  ('Q7571821', 'Soviet–Lithuanian Mutual Assistance Treaty', 'The Soviet–Lithuanian Mutual Assistance Treaty (Lithuanian: Lietuvos-Sovietų Sąjungos savitarpio pagalbos sutartis, Russian: советско-литовский договор о взаимопомощи, romanized: sovetsko-litovskiy dogovor o vzaimopomoshchi) was a bilateral treaty signed between the Soviet Union and Lithuania on October 10, 1939. According to provisions outlined in the treaty, Lithuania would acquire about one fifth of the Vilnius Region, including Lithuania''s historical capital, Vilnius, and in exchange would allow five Soviet military bases with 20,000 troops to be established across Lithuania.', 1939, 10, 10, NULL, NULL, NULL, 'day', '10 October 1939', 53, 'https://en.wikipedia.org/wiki/Soviet%E2%80%93Lithuanian_Mutual_Assistance_Treaty'),
  ('Q58473', 'occupation of the Baltic states', 'The Baltic states—Estonia, Latvia, and Lithuania—were occupied and annexed by the Soviet Union in 1940 and remained under its control until its dissolution in 1991. For a period of several years during World War II, Nazi Germany occupied the Baltic states after it invaded the Soviet Union in 1941.', 1940, NULL, NULL, 1991, NULL, NULL, 'year', '1940–1991', 69, 'https://en.wikipedia.org/wiki/Occupation_of_the_Baltic_states'),
  ('Q931639', 'Rainiai massacre', 'The Rainiai massacre (Lithuanian: Rainių žudynės) was the mass murder of between 70 and 80 Lithuanian political prisoners by the NKVD, with help from the Red Army, in a forest near Telšiai, Lithuania, during the night of June 24–25, 1941. It was one of many similar massacres carried out by Soviet forces in Lithuania, and other areas under the control of the Soviet Union, during June 1941.', 1941, 6, NULL, NULL, NULL, NULL, 'month', 'June 1941', 45, 'https://en.wikipedia.org/wiki/Rainiai_massacre'),
  ('Q1324428', 'Baltic Operation', 'The Baltic strategic defensive operation (Russian: Прибалтийская стратегическая оборонительная операция, romanized: Pribaltiyskaya strategicheskaya oboronitel''naya operatsiya) encompassed the operations of the Red Army from 22 June to 9 July 1941 conducted over the territories of Soviet-occupied Lithuania, Latvia, and Estonia in response to the offensive launched by the Wehrmacht in Operation Barbarossa.', 1941, 7, 9, NULL, NULL, NULL, 'day', '9 July 1941', 56, 'https://en.wikipedia.org/wiki/Baltic_operation'),
  ('Q1528565', 'Battle of Rossieny', 'The Battle of Raseiniai (23–27 June 1941) was a large tank battle that took place in the early stages of Operation Barbarossa, the German invasion of the Soviet Union. The battle was fought between the elements of the German 4th Panzer Group and the Soviet 3rd Mechanized Corps with the 12th Mechanised Corps, in Lithuania, 75 km (47 mi) north-west of Kaunas.', 1941, 6, 23, 1941, 6, 27, 'day', '23 June 1941 – 27 June 1941', 61, 'https://en.wikipedia.org/wiki/Battle_of_Raseiniai'),
  ('Q2083668', 'German occupation of Lithuania during World War II', 'The military occupation of Lithuania by Nazi Germany lasted from the German invasion of the Soviet Union on 22 June 1941 to the end of the Battle of Memel on 28 January 1945. At first, the Germans were welcomed as liberators from the repressive Soviet regime which had occupied Lithuania.', 1941, 6, 22, 1945, 1, 28, 'day', '22 June 1941 – 28 January 1945', 48, 'https://en.wikipedia.org/wiki/German_occupation_of_Lithuania_during_World_War_II'),
  ('Q2669609', 'Kaunas pogrom', 'The Kaunas pogrom was a massacre of Jews living in Kaunas, Lithuania, that took place on 25–29 June 1941; the first days of Operation Barbarossa and the Nazi occupation of Lithuania. The most infamous incident occurred at the garage of NKVD Kaunas section, a nationalized garage of Lietūkis, an event known as the Lietūkis Garage Massacre.', 1941, 6, 27, NULL, NULL, NULL, 'day', '27 June 1941', 59, 'https://en.wikipedia.org/wiki/Kaunas_pogrom'),
  ('Q4205775', 'June Uprising in Lithuania', 'The June Uprising (Lithuanian: Birželio sukilimas) was a brief period in late June 1941 between the first Soviet and the Nazi occupations. A year earlier, on June 15, 1940, the Red Army occupied Lithuania and established the unpopular Lithuanian Soviet Socialist Republic, which silenced its critics and suppressed resistance with political repression and state terrorism.', 1941, NULL, NULL, NULL, NULL, NULL, 'year', '1941', 57, 'https://en.wikipedia.org/wiki/June_Uprising_in_Lithuania'),
  ('Q7075770', 'German occupation of the Baltic states during World War II', 'After the German invasion of the Soviet Union, the Baltic states were under military occupation by Nazi Germany from 1941 to 1944. Initially, many Estonians, Latvians, and Lithuanians considered the Germans liberators from the Soviet Union.', 1941, 7, NULL, 1944, NULL, NULL, 'month', 'July 1941 – 1944', 37, 'https://en.wikipedia.org/wiki/German_occupation_of_the_Baltic_states_during_World_War_II'),
  ('Q12029011', 'Kaunas massacre of October 29, 1941', 'The Kaunas massacre of October 29, 1941, also known as the Great Action, was the largest mass murder of Lithuanian Jews. 9,200 people among them 2,007 Jewish men, 2,920 women, and 4,273 children were murdered in a single day at the Ninth Fort.', 1941, 10, 29, NULL, NULL, NULL, 'day', '29 October 1941', 41, 'https://en.wikipedia.org/wiki/Kaunas_massacre_of_October_29%2C_1941'),
  ('Q719515', 'Operation Ostra Brama', 'Operation Ostra Brama (Polish: Operacja „Ostra Brama”, lit. ''Operation Sharp Gate'') was the Polish Home Army''s attempted takeover of Vilnius (Polish: Wilno) in wake of the German Wehrmacht''s evacuation, ahead of the approaching Soviet Red Army''s Vilnius offensive. A part of a Polish national uprising, Operation Tempest, the action happened on 7–13 July 1944.', 1944, 7, 7, 1944, 7, 15, 'day', '7 July 1944 – 15 July 1944', 43, 'https://en.wikipedia.org/wiki/Operation_Ostra_Brama'),
  ('Q2661048', 'Vilnius Offensive', 'The Vilnius offensive (Lithuanian: Vilniaus operacija; Russian: Вильнюсская наступательная операция, lit. ''Vilnius offensive operation'') occurred as part of the third phase of Operation Bagration, the Soviet Red Army''s strategic summer offensive against the German Wehrmacht in June and July 1944. It lasted from 5 July to 13 July 1944 and ended with a Soviet victory.', 1944, 7, NULL, NULL, NULL, NULL, 'month', 'July 1944', 50, 'https://en.wikipedia.org/wiki/Vilnius_offensive'),
  ('Q3077958', 'Šiauliai Offensive', 'The Šiauliai offensive (Russian: Шяуляйская операция) was an operation of the Soviet forces of the 1st Baltic Front, commanded by General Hovhannes Bagramyan, conducted from 5 July to 29 August 1944, during the Second World War. It was part of the third phase of the Belorussian strategic offensive operation (also known as Operation Bagration), and drove German troops from much of Lithuania, with the main tactical objective of the city of Šiauliai (Russian: Шяуля́й, German: Schaulen).', 1944, 7, 5, NULL, NULL, NULL, 'day', '5 July 1944', 45, 'https://en.wikipedia.org/wiki/%C5%A0iauliai_offensive'),
  ('Q3620958', 'Battle of Memel', 'The Battle of Memel or the siege of Memel (German: Erste Kurlandschlacht) was a battle which took place on the Eastern Front during World War II. The battle began when the Red Army launched its Memel offensive operation (Russian: Мемельская наступательная операция) in late 1944. The offensive drove remaining German forces in the area that is now Lithuania and Latvia into a small bridgehead in Klaipėda (Memel) and its port, leading to a three-month siege of that position.', 1944, 10, 5, 1945, 1, 28, 'day', '5 October 1944 – 28 January 1945', 57, 'https://en.wikipedia.org/wiki/Battle_of_Memel'),
  ('Q5310753', 'Dubingiai massacre', 'The Dubingiai massacre was a mass murder of Lithuanian civilians committed by the Polish Home Army (AK) in the town of Dubingiai and its surroundings on 23 June 1944. The Dubingiai massacre started a wider Polish Home Army (AK) operation in which units beyond the 5th Brigade were involved.', 1944, 6, 23, NULL, NULL, NULL, 'day', '23 June 1944', 37, 'https://en.wikipedia.org/wiki/Dubingiai_massacre'),
  ('Q595321', 'Singing Revolution', 'The Singing Revolution was a series of events from 1987 to 1991 that led to the restoration of independence of the three Soviet-occupied Baltic countries of Estonia, Latvia, and Lithuania at the end of the Cold War. The Soviet Union annexed the Baltics around 1940, following the Molotov-Ribbentrop Pact (a non-aggression agreement with Nazi Germany), though this annexation was not widely recognized.', 1987, NULL, NULL, 1991, NULL, NULL, 'year', '1987–1991', 73, 'https://en.wikipedia.org/wiki/Singing_Revolution'),
  ('Q2823577', 'Act of the Re-Establishment of the State of Lithuania', 'The Act of the Re-Establishment of the State of Lithuania or Act of 11 March (Lithuanian: Aktas dėl Lietuvos nepriklausomos valstybės atstatymo) was an independence declaration by Lithuania adopted on 11 March 1990, signed by all members of the Supreme Council of the Republic of Lithuania led by Sąjūdis. The act emphasized restoration and legal continuity of the interwar-period Lithuania, which was occupied by the Soviet Union and annexed in June 1940.', 1990, 3, 11, NULL, NULL, NULL, 'day', '11 March 1990', 57, 'https://en.wikipedia.org/wiki/Act_of_the_Re-Establishment_of_the_State_of_Lithuania'),
  ('Q3736097', 'Soviet OMON assaults on Lithuanian border posts', 'Several Soviet OMON (Special Purpose Police Unit) assaults on Lithuanian border posts occurred after Lithuania declared its independence from the Soviet Union on 11 March 1990. As a Soviet republic, the Lithuanian SSR did not have a state border with customs or checkpoints.', 1990, 12, NULL, 1991, 8, NULL, 'month', 'December 1990 – August 1991', 43, 'https://en.wikipedia.org/wiki/Soviet_OMON_assaults_on_Lithuanian_border_posts'),
  ('Q1540695', 'January Events', 'The January Events (Lithuanian: Sausio įvykiai) were a series of violent confrontations between the civilian population of Lithuania, supporting independence, and the Soviet Armed Forces. The events took place between 11 and 13 January 1991, after the restoration of independence by Lithuania.', 1991, 1, 13, 1991, 1, 13, 'day', '13 January 1991', 68, 'https://en.wikipedia.org/wiki/January_Events'),
  ('Q5177982', '1993 Pakaunė mutiny', 'The 1993 Pakaunė mutiny (Lithuanian: Pakaunės savanorių maištas) was a stand-off that occurred in summer 1993 in Lithuania near Kaunas between a group of about 150 men from the Lithuanian National Defence Volunteer Forces (then known as Savanoriškoji krašto apsaugos tarnyba or SKAT) and the Lithuanian government. There was mutual distrust between SKAT and the newly elected leftist Democratic Labour Party of Lithuania (LDDP).', 1993, 7, 31, 1993, 9, 22, 'day', '31 July 1993 – 22 September 1993', 34, 'https://en.wikipedia.org/wiki/1993_Pakaun%C4%97_mutiny'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q2568194', 'Lithuanian nuclear power referendum', 'A referendum on extending the operation of the Ignalina Nuclear Power Plant was held in Lithuania on 12 October 2008 alongside parliamentary elections. The country''s government was obliged to close down Ignalina as part of its treaty of accession to the European Union.', 2008, 10, 12, NULL, NULL, NULL, 'day', '12 October 2008', 43, 'https://en.wikipedia.org/wiki/2008_Lithuanian_nuclear_power_referendum'),
  ('Q391126', 'Lithuanian nuclear power referendum', 'An advisory referendum on the construction of a new nuclear power station was held in Lithuania on 14 October 2012, alongside parliamentary elections. The proposal was rejected by 65% of voters.', 2012, 10, 14, NULL, NULL, NULL, 'day', '14 October 2012', 41, 'https://en.wikipedia.org/wiki/2012_Lithuanian_nuclear_power_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q131319476', 'Swiftair Flight 5960', 'Swiftair Flight 5960 (operating as European Air Transport Leipzig Flight 18D) was an international cargo flight that crashed early in the morning on 25 November 2024 while on final approach to Vilnius Airport. The aircraft, a Boeing 737-400, was flying from Leipzig/Halle Airport in Leipzig, Germany, to Vilnius Airport in Vilnius, Lithuania, when it crashed into the ground short of the runway and came to a stop near a two-story house in Liepkalnis.', 2024, 11, 25, NULL, NULL, NULL, 'day', '25 November 2024', 57, 'https://en.wikipedia.org/wiki/Swiftair_Flight_5960');
